const OVERSTAY_REASONS=["Exploring financing options","Finance application","Clarifying product specifications","Price negotiations","General conversation with customer","Discussion of styles and designs","Completion of paperwork","Answering customer questions","Late arrival"]
function parseOverstayReasons(value){if(Array.isArray(value))return value;const text=String(value||"").trim();if(!text)return [];return text.split(/\s*;\s*/).filter(Boolean).filter(reason=>OVERSTAY_REASONS.includes(reason))}
