function normalise(v){return String(v||"").trim().toLowerCase()}
function isSold(v){return normalise(v)==="sold"}
function submittedBy(user){return String(user?.user_metadata?.full_name||user?.user_metadata?.name||"").trim()||user?.email||"Unknown"}
