 async function confirmAppointment(){if(!appointment?.appointment_row_id||confirming)return;setConfirming(true);setConfirmError("");let actionId=null;try{const{data:userData,error:userError}=await supabase.auth.getUser();if(userError)throw userError;const by=submittedBy(userData?.user),now=new Date().toISOString();const{data:action,error:actionError}=await supabase.from("action_runs").insert({action_type:"confirm_appointment",status:"running",entity_type:"appointment",entity_id:appointment.appointment_row_id,triggered_by:by,started_at:now,input_data:{appointment_row_id:appointment.appointment_row_id}}).select("id").single();if(actionError)throw actionError;actionId=action.id;const{data:updated,error:updateError}=await supabase.from("appointments").update({cps_c:true}).eq("appointment_row_id",appointment.appointment_row_id).select("*").single();if(updateError)throw updateError;const{error:actionUpdateError}=await supabase.from("action_runs").update({status:"completed",completed_at:new Date().toISOString(),output_data:{appointment_row_id:updated.appointment_row_id,cps_c:true}}).eq("id",actionId);if(actionUpdateError)throw actionUpdateError;setCps(v=>({...v,cps_c:true}));onUpdated?.(updated)}catch(e){console.error("Confirm Appointment action failed:",e);const msg=e?.message||"Unable to confirm appointment.";setConfirmError(msg);if(actionId)await supabase.from("action_runs").update({status:"failed",completed_at:new Date().toISOString(),error_message:msg}).eq("id",actionId)}finally{setConfirming(false)}}
